mapper.select:
select
wodm.*
from wms_outbound_detail_manufactured wodm
join wms_outbound_manufactured wod on wodm.outbound_manufactured_id = wod.id and wod.bool_delete_enum = 0 and wod.review_status = 2
where wodm.bool_delete_enum = 0

    and wodm.basic_class & #{basicClass} > 0


    and wodm.project_id = #{projectId}


    
        and wod.application_time > #{applicationTime[0]}
    
    
        and wod.application_time < #{applicationTime[1]}
    


    
        and wod.review_pass_time >= #{reviewPassTime[0]}
    
    
        and wod.review_pass_time <= #{reviewPassTime[1]}
    


    and wod.serial_number like CONCAT('%', #{serialNumber},'%')


    and wodm.specification like concat('%',#{specification},'%')
